import{_ as e,o as r,c as t,a5 as i}from"./chunks/framework.CX7j2CRp.js";const _=JSON.parse('{"title":"技术类博客写作指导","description":"","frontmatter":{},"headers":[],"relativePath":"public/prompt/博客/文章模板/技术.md","filePath":"public/prompt/博客/文章模板/技术.md","lastUpdated":1791612145000}'),l={name:"public/prompt/博客/文章模板/技术.md"};function o(h,a,n,d,p,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="技术类博客写作指导" tabindex="-1">技术类博客写作指导 <a class="header-anchor" href="#技术类博客写作指导" aria-label="Permalink to &quot;技术类博客写作指导&quot;">​</a></h1><h2 id="文章定位" tabindex="-1">文章定位 <a class="header-anchor" href="#文章定位" aria-label="Permalink to &quot;文章定位&quot;">​</a></h2><p>技术类博客用于整理当前聊天中讨论过的工程问题、实现方案、架构设计或排障过程，形成便于复盘和维护的技术笔记。</p><p>内容以当前聊天上下文和已核实的代码、配置、测试结果为依据。不得擅自假设项目技术栈、模块职责、运行环境、性能指标或已经完成的验证。未确认的信息必须明确说明。</p><h2 id="开头摘要与配图" tabindex="-1">开头摘要与配图 <a class="header-anchor" href="#开头摘要与配图" aria-label="Permalink to &quot;开头摘要与配图&quot;">​</a></h2><p>正文先用一段纯文本概述讨论主题、要解决的问题以及主要结论，避免以图片、HTML 或代码块开头，影响 VitePress 文章列表的概览展示。</p><p>只有图示确实有助于理解结构或流程时才配图。可使用 Mermaid 流程图、时序图、模块关系图或必要的截图；图示必须与实际讨论内容一致，不为装饰而添加图片。</p><h2 id="推荐结构" tabindex="-1">推荐结构 <a class="header-anchor" href="#推荐结构" aria-label="Permalink to &quot;推荐结构&quot;">​</a></h2><p>根据主题选取适用章节，不强制填满。</p><h3 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h3><p>说明问题出现的环境、已有行为、希望达到的效果，以及需要遵守的约束。</p><h3 id="_2-模块职责与边界" tabindex="-1">2. 模块职责与边界 <a class="header-anchor" href="#_2-模块职责与边界" aria-label="Permalink to &quot;2. 模块职责与边界&quot;">​</a></h3><p>涉及架构时优先说明系统分层、模块输入输出、各自负责与不负责的事项，以及外部依赖。</p><h3 id="_3-方案与核心机制" tabindex="-1">3. 方案与核心机制 <a class="header-anchor" href="#_3-方案与核心机制" aria-label="Permalink to &quot;3. 方案与核心机制&quot;">​</a></h3><p>先说明整体思路，再解释关键技术原理、数据流和控制流。保留必要的英文技术术语、协议名称和版本信息，避免只有结论而没有原因。</p><h3 id="_4-正常流程与异常路径" tabindex="-1">4. 正常流程与异常路径 <a class="header-anchor" href="#_4-正常流程与异常路径" aria-label="Permalink to &quot;4. 正常流程与异常路径&quot;">​</a></h3><p>按实际执行顺序描述关键步骤、状态变化以及失败时的处理方式。涉及并发、权限、超时、重试、幂等或回滚时，说明其适用边界。</p><h3 id="_5-实现与验证" tabindex="-1">5. 实现与验证 <a class="header-anchor" href="#_5-实现与验证" aria-label="Permalink to &quot;5. 实现与验证&quot;">​</a></h3><p>只展示理解问题所需的配置、接口、伪代码或代码片段，不堆砌完整源码。区分已执行测试、从代码推断的行为和仍待验证的假设；不要虚构命令输出与测试结论。</p><h3 id="_6-取舍与后续事项" tabindex="-1">6. 取舍与后续事项 <a class="header-anchor" href="#_6-取舍与后续事项" aria-label="Permalink to &quot;6. 取舍与后续事项&quot;">​</a></h3><p>交代方案的优点、代价、潜在风险、备选方案与后续检查点。</p><h2 id="写作原则" tabindex="-1">写作原则 <a class="header-anchor" href="#写作原则" aria-label="Permalink to &quot;写作原则&quot;">​</a></h2><ul><li>优先讲目标、架构分层、职责边界、正常流程和异常路径。</li><li>整理口语化讨论，修正错字与重复表达，但不改变原始技术结论。</li><li>不进行与当前主题无关的百科式扩展，也不制造未经讨论的实现细节。</li><li>不泄露凭据、Token、私钥及其他敏感配置；必要时使用脱敏示例。</li><li>简单问题可以使用短结构；复杂问题以准确、可验证、可复盘为优先。</li></ul>',23)])])}const u=e(l,[["render",o]]);export{_ as __pageData,u as default};
